$runtime=new App\Core\Runtime($root);$runtime->license()->enforce($runtime->baseUrl());$db=App\Core\Runtime::connect($runtime->read('installed')['database']);$events=new App\Core\EventBus();$cms=new App\Core\CmsRepository($db,$events,$runtime);
