    foreach(array_reverse((array)($state['updated']??[]),true)as$path=>$saved){$page=$cms->pageAtPath((string)$path);$document=$page?$cms->builderDocument((int)$page['id']):null;if(!$page||!$document||(int)$document['builder_version']!==(int)$saved['applied_version'])throw new RuntimeException('An updated page changed; rollback stopped: '.$path);$before=PageBuilder::sanitizeBlocks((array)$saved['document']['blocks'],$catalog,$locales);$cms->saveBuilderDocument((int)$page['id'],(int)$document['builder_version'],$owner,'sensecms',$before,array_keys($catalog));$cms->savePage($input($saved['page']),$translations($saved['page']['translations']),$owner);}
