}

if(file_exists($journal))throw new RuntimeException('Existing AI product-page journal requires review.');foreach(['/','/platform']as$path)if(!$cms->pageAtPath($path))throw new RuntimeException('Required managed product page is missing: '.$path);if($cms->pageAtPath('/platform/ai'))throw new RuntimeException('The AI product page already exists and requires review.');
$slug='platform-ai';$check=$db->prepare('SELECT 1 FROM page_translations WHERE facility_id=? AND locale="en" AND slug=?');$check->execute([(int)$facility['id'],$slug]);if($check->fetchColumn())throw new RuntimeException('The AI page slug is already in use.');
$state=['status'=>'applying','updated'=>[],'created'=>[],'settings'=>[]];$write($state);
$promotions=[
    '/'=>['AI that keeps editors in control','Draft and refine Page Builder sections and posts, maintain a governed Knowledge Base for RAG, and choose your own configured AI provider. Human review stays in the publishing flow.','Explore Sense CMS AI →'],
    '/platform'=>['Provider-neutral AI in Core','Sense CMS combines editorial AI, per-provider budgets, a controlled RAG index and evaluation-ready training data. Themes still own presentation; Core owns content, permissions and review.','Discover the AI platform →'],
];
foreach($promotions as$path=>[$title,$text,$label]){$page=$cms->pageAtPath($path);$id=(int)$page['id'];$before=$cms->pageAdmin($id);$document=$cms->builderDocument($id);if(!$before||!$document)throw new RuntimeException('Cannot load managed page: '.$path);$state['updated'][$path]=['page'=>$before,'document'=>$document,'applied_version'=>null];$write($state);$blocks=PageBuilder::sanitizeBlocks((array)$document['blocks'],$catalog,$locales);$blocks[]=$block($title,$text,$label,'/platform/ai');$version=$cms->saveBuilderDocument($id,(int)$document['builder_version'],$owner,'sensecms',$blocks,array_keys($catalog));$state['updated'][$path]['applied_version']=$version;$write($state);}
$description='Provider-neutral AI for Page Builder and posts, a controlled Knowledge Base with RAG, budget guardrails, human review and local training-data preparation.';
$pageTranslations=['en'=>['title'=>'AI content management, built into Sense CMS','slug'=>$slug,'excerpt'=>$description,'seo_title'=>'AI Content Management, RAG & Editorial Assistance | Sense CMS','seo_description'=>'Use review-first AI in Sense CMS for Page Builder and posts, with a controlled Knowledge Base, RAG, provider budgets and human approval.']];
$id=$cms->savePage(['id'=>0,'facility_id'=>(int)$facility['id'],'public_path'=>'/platform/ai','template'=>'product','status'=>'draft','visibility'=>'public','published_at'=>null],$pageTranslations,$owner);$state['created']['/platform/ai']=['id'=>$id,'version'=>0];$write($state);
$sections=[
    ['AI for structured editorial work','Generate or improve drafts inside Page Builder and Posts without bypassing editorial review. Suggestions remain editable and publication stays a deliberate human action.'],
    ['One Core, multiple AI providers','Configure OpenAI Responses, compatible APIs, Anthropic or Google Gemini independently. Encrypted credentials, priorities and request, token and budget guardrails keep provider choice under installation control.'],
    ['Knowledge Base and RAG','Combine approved website content, manual knowledge and private text documents in a local, traceable retrieval index. Sources can be included, corrected, disabled or deleted independently.'],
