];$blocks=[];foreach($sections as[$title,$text])$blocks[]=$block($title,$text);$version=$cms->saveBuilderDocument($id,0,$owner,'sensecms',$blocks,array_keys($catalog));$state['created']['/platform/ai']['version']=$version;$write($state);$cms->savePage(['id'=>$id,'facility_id'=>(int)$facility['id'],'public_path'=>'/platform/ai','template'=>'product','status'=>'published','visibility'=>'public','published_at'=>null],$pageTranslations,$owner);
